/* 京东网页 Cookie 捕获 / Loon 手动登录校验。
 * EXPERIMENTAL: real-device compatibility and bean query verification pending.
 * See jd-cookie-local/README.md and NOTICE.md. Generated by tools/build.mjs.
 * No wskey conversion, signing, uploads or automatic refresh.
 */
(function () {
'use strict';
// Pure helpers for browser Cookie capture. No signing, network or storage here.
function createCore() {
  'use strict';
  function check(value, code) { if (!value) { const e = new Error(code); e.code = code; throw e; } }
  function pinIdentity(pin) {
    check(typeof pin === 'string' && pin.length > 0 && pin.length <= 1024 && /^[\x21-\x7e]+$/.test(pin) && !/[;,"\\]/.test(pin), 'PIN_FORMAT');
    let value; try { value = decodeURIComponent(pin); } catch (_) { check(false, 'PIN_FORMAT'); }
    check(value && !/[\x00-\x1f\x7f]/.test(value), 'PIN_FORMAT'); return value;
  }
  function headerValues(headers) {
    check(headers && typeof headers === 'object' && !Array.isArray(headers), 'HEADER_FORMAT');
    return Object.keys(headers).filter(k => k.toLowerCase() === 'cookie')
      .flatMap(k => Array.isArray(headers[k]) ? headers[k] : [headers[k]]);
  }
  function fromHeaders(headers) {
    const raw = headerValues(headers);
    if (!raw.length) return {code:'WEB_NO_COOKIE',account:null};
    check(raw.every(x => typeof x === 'string' && x.length <= 32768), 'COOKIE_FORMAT');
    const text = raw.join('; '), values = Object.create(null);
    check(text.length <= 32768 && !/[\x00-\x08\x0a-\x1f\x7f]/.test(text), 'COOKIE_FORMAT');
    for (const field of text.split(';')) {
      const index = field.indexOf('='), name = (index < 0 ? field : field.slice(0,index)).trim();
      if (name !== 'pt_key' && name !== 'pt_pin') continue;
      check(index >= 0, 'COOKIE_FORMAT');
      let value = field.slice(index + 1).trim();
      if (value.length >= 2 && value.startsWith('"') && value.endsWith('"')) value = value.slice(1,-1);
      check(!Object.prototype.hasOwnProperty.call(values,name) || values[name] === value, 'COOKIE_CONFLICT');
      values[name] = value;
    }
    const has = name => Object.prototype.hasOwnProperty.call(values,name);
    if (has('pt_key')) check(/^[A-Za-z0-9._~+/=-]{8,4096}$/.test(values.pt_key) && !/^(fake|deleted|null|undefined|xxx)/i.test(values.pt_key), 'PT_KEY_REJECTED');
    const userName = has('pt_pin') ? pinIdentity(values.pt_pin) : null;
    if (!has('pt_key') || !has('pt_pin')) return {code:'WEB_INCOMPLETE',account:null};
    return {code:'WEB_CAPTURED',account:{userName,cookie:`pt_key=${values.pt_key}; pt_pin=${values.pt_pin};`}};
  }
  function capture(request) {
    check(typeof request?.url === 'string' && request.url.length <= 8192 && !/[\s\x00-\x1f\x7f]/.test(request.url), 'CAPTURE_URL');
    const match = /^https:\/\/(m\.jd\.com|home\.m\.jd\.com|my\.m\.jd\.com)(?:[/?#]|$)/.exec(request.url);
    check(match, 'CAPTURE_URL');
    return {...fromHeaders(request.headers),host:match[1]};
  }
  function accountFromCookie(cookie) {
    const result = fromHeaders({Cookie:cookie}); check(result.account, 'COOKIE_INCOMPLETE'); return result.account;
  }
  function validAccount(account) {
    check(account && typeof account.userName === 'string' && typeof account.cookie === 'string', 'STORAGE_FORMAT');
    const normalized = accountFromCookie(account.cookie);
    check(normalized.userName === account.userName && normalized.cookie === account.cookie, 'STORAGE_FORMAT');
    return normalized;
  }
  function label(userName) { return '***' + userName.replace(/[^a-zA-Z0-9\u3400-\u9fff]/g,'').slice(-2); }
  function loginValid(data, account) {
    check(data && (data.retcode === 0 || data.retcode === '0'), 'LOGIN_UNCONFIRMED');
    const identity = data?.data?.userInfo?.baseInfo?.curPin;
    if (identity !== undefined) check(typeof identity === 'string' && (identity === account.userName || pinIdentity(identity) === account.userName), 'ACCOUNT_MISMATCH');
  }
  function verifyOptions(account) {
    const normalized = validAccount(account);
    return {method:'get',url:'https://me-api.jd.com/user_new/info/GetJDUserInfoUnion',timeout:10000,
      'auto-redirect':false,'auto-cookie':false,insecure:false,
      headers:{Cookie:normalized.cookie,Referer:'https://my.m.jd.com/index.html','Accept-Encoding':'identity',
        'User-Agent':'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1'}};
  }
  return Object.freeze({check,pinIdentity,fromHeaders,capture,accountFromCookie,validAccount,label,loginValid,verifyOptions});
}

// Capture and status are local-only. Verification is an explicit manual action.
async function runWorkflow(core, env) {
  'use strict';
  const keys = {capture:'jdWebCaptureV1',observation:'jdWebObservationV1',notice:'jdWebNoticeV1',
    state:'jdWebVerifyV1',cookies:'jdCookieList',status:'jdLocalStatusV1'};
  const codes = new Set(['WEB_CAPTURED','WEB_NO_COOKIE','WEB_INCOMPLETE','WEB_NOT_SEEN','LOGIN_VERIFIED',
    'PIN_FORMAT','HEADER_FORMAT','COOKIE_FORMAT','COOKIE_CONFLICT','PT_KEY_REJECTED','COOKIE_INCOMPLETE','CAPTURE_URL',
    'STORAGE_FORMAT','STORAGE_WRITE_FAILED','CLOCK_INVALID','RANDOM_SOURCE','LOGIN_UNCONFIRMED','ACCOUNT_MISMATCH','MODE_REQUIRED',
    'WEB_CAPTURE_REQUIRED','WEB_EXPIRED','VERIFY_BUSY','VERIFY_COOLDOWN','VERIFY_SUPERSEDED','CAPTURE_CHANGED',
    'RATE_LIMITED','HTTP_REJECTED','RESPONSE_FORMAT','RESPONSE_JSON','ACCOUNT_LIMIT','NETWORK_ERROR','NETWORK_TIMEOUT','INTERNAL_ERROR']);
  const read = key => {
    const raw = env.read(key); if (!raw) return null;
    core.check(typeof raw === 'string' && raw.length <= 1048576,'STORAGE_FORMAT');
    try { return JSON.parse(raw); } catch (_) { core.check(false,'STORAGE_FORMAT'); }
  };
  const save = (key,value) => core.check(env.write(JSON.stringify(value),key) === true,'STORAGE_WRITE_FAILED');
  const clock = () => { const t = env.now(); core.check(Number.isSafeInteger(t) && t >= 0,'CLOCK_INVALID'); return t; };
  const id = () => { const r = env.random(); core.check(Number.isFinite(r) && r >= 0 && r < 1,'RANDOM_SOURCE'); return String(clock()) + ':' + r.toString(36).slice(2); };
  const candidate = () => {
    const c = read(keys.capture); if (!c) return null;
    core.check(c.version === 1 && typeof c.id === 'string' && c.id.length > 0 && c.id.length <= 100 && Number.isSafeInteger(c.capturedAt),'STORAGE_FORMAT');
    core.check(c.verifiedAt == null || (Number.isSafeInteger(c.verifiedAt) && c.verifiedAt >= 0 && c.verifiedAt <= clock()),'STORAGE_FORMAT');
    core.validAccount(c.account); return c;
  };
  const fresh = c => c && clock() >= c.capturedAt && clock() - c.capturedAt < 900000;
  const report = (code,c,automatic=false,force=false) => {
    const time = clock(), observation = read(keys.observation);
    core.check(codes.has(code) && (!observation || (codes.has(observation.code) && Number.isSafeInteger(observation.at))),'STORAGE_FORMAT');
    save(keys.status,{mode:'web',status:code,at:time,account:c ? core.label(c.account.userName) : null,
      lastRequest:observation?.code || 'WEB_NOT_SEEN',lastRequestAt:observation?.at || null,
      loginVerification:c?.verifiedAt ? 'verified' : 'pending',queryVerification:'pending'});
    if (automatic && !force) {
      const last = read(keys.notice);
      if (last?.code === code && Number.isSafeInteger(last.at) && time >= last.at && time - last.at < 60000) return;
    }
    if (automatic) save(keys.notice,{code,at:time});
    env.notify(code,c ? core.label(c.account.userName) : '');
  };
  let owned = null;
  try {
    if (env.request) {
      const result = core.capture(env.request), time = clock();
      save(keys.observation,{code:result.code,at:time,host:result.host});
      if (!result.account) { report(result.code,null,true);return {status:result.code}; }
      const previous = candidate(), same = previous?.account.cookie === result.account.cookie;
      const c = {version:1,id:same ? previous.id : id(),capturedAt:time,account:result.account,
        verifiedAt:same && fresh(previous) && time - previous.verifiedAt < 900000 ? previous.verifiedAt || null : null};
      save(keys.capture,c);
      const code = c.verifiedAt ? 'LOGIN_VERIFIED' : 'WEB_CAPTURED';
      report(code,c,true,!same); return {status:code};
    }
    core.check(env.mode === 'status' || env.mode === 'verify','MODE_REQUIRED');
    const c = candidate(), observation = read(keys.observation);
    if (env.mode === 'status') {
      let code = c ? (fresh(c) ? (c.verifiedAt ? 'LOGIN_VERIFIED' : 'WEB_CAPTURED') : 'WEB_EXPIRED') : observation?.code || 'WEB_NOT_SEEN';
      if (code === 'WEB_CAPTURED' && !c) code = 'WEB_NOT_SEEN';
      if (c && !fresh(c)) save(keys.capture,null);
      report(code,c);return {status:code};
    }
    core.check(c,'WEB_CAPTURE_REQUIRED');
    if (!fresh(c)) { save(keys.capture,null);core.check(false,'WEB_EXPIRED'); }
    const time = clock(), state = read(keys.state);
    if (state) {
      core.check(Number.isSafeInteger(state.startedAt) && state.startedAt <= time,'STORAGE_FORMAT');
      core.check(state.status !== 'inflight' || time - state.startedAt >= 30000,'VERIFY_BUSY');
      core.check(state.captureId !== c.id || time - state.startedAt >= 60000,'VERIFY_COOLDOWN');
    }
    const nonce = id(); save(keys.state,{nonce,captureId:c.id,startedAt:time,status:'inflight'});owned = nonce;
    await env.wait(100);
    const owns = () => {
      core.check(read(keys.state)?.nonce === nonce,'VERIFY_SUPERSEDED');
      const current = candidate();
      core.check(current?.id === c.id && current.account.cookie === c.account.cookie,'CAPTURE_CHANGED');
    };
    owns();
    const response = await env.http(core.verifyOptions(c.account)); owns();
    core.check(response && response.status === 200,response?.status === 429 ? 'RATE_LIMITED' : 'HTTP_REJECTED');
    core.check(typeof response.body === 'string' && response.body.length <= 262144,'RESPONSE_FORMAT');
    let data; try { data = JSON.parse(response.body); } catch (_) { core.check(false,'RESPONSE_JSON'); }
    core.loginValid(data,c.account);
    const accounts = read(keys.cookies) || [];
    core.check(Array.isArray(accounts) && accounts.length <= 50,'STORAGE_FORMAT');
    const seen = new Set();
    for (const account of accounts) { core.validAccount(account);core.check(!seen.has(account.userName),'STORAGE_FORMAT');seen.add(account.userName); }
    const index = accounts.findIndex(a => a.userName === c.account.userName);
    if (index < 0) { core.check(accounts.length < 50,'ACCOUNT_LIMIT');accounts.push(c.account); } else accounts[index] = c.account;
    owns();save(keys.cookies,accounts);
    owns();const latest = candidate();save(keys.capture,{...latest,verifiedAt:clock()});
    save(keys.state,{nonce,captureId:c.id,startedAt:time,status:'confirmed'});
    report('LOGIN_VERIFIED',{...c,verifiedAt:clock()});return {status:'LOGIN_VERIFIED',queryVerification:'pending'};
  } catch (error) {
    const code = codes.has(error?.code) ? error.code : 'INTERNAL_ERROR';
    if (owned) { try { const s = read(keys.state);if (s?.nonce === owned) save(keys.state,{...s,status:'failed',code}); } catch (_) {} }
    if (env.request) { try { save(keys.observation,{code,at:clock()}); } catch (_) {} }
    try { report(code,null,!!env.request); } catch (_) { try { env.notify(code,''); } catch (_) {} }
    return {status:'failed',code};
  } finally { env.done({}); }
}

// Loon adapter. Every captured browser request is forwarded unchanged.
(function () {
  'use strict';
  const core = createCore(); let finished = false;
  function done() { if (!finished) { finished = true;$done({}); } }
  function fail(code) { const error = new Error(code);error.code = code;return error; }
  const messages = {
    WEB_CAPTURED:'已捕获网页 Cookie。请在 Loon 手动运行“京东网页Cookie校验并保存”，十五分钟内有效。',
    LOGIN_VERIFIED:'Cookie 登录校验通过，已保存至 BoxJs“京东本地Cookie”。京豆查询仍待验收。',
    WEB_NOT_SEEN:'尚未看到网页请求。请确认插件与 MitM 已启用，再用 Safari 打开 https://my.m.jd.com/index.html。',
    WEB_NO_COOKIE:'已看到网页请求，但没有 Cookie。请在 Safari 登录京东，再打开网页“我的”。',
    WEB_INCOMPLETE:'已看到网页请求，但未带完整 pt_key/pt_pin。请在 Safari 完成登录，再打开网页“我的”。',
    WEB_CAPTURE_REQUIRED:'还没有捕获完整网页 Cookie。请在 Safari 登录京东，再打开 https://my.m.jd.com/index.html。',
    WEB_EXPIRED:'暂存网页 Cookie 已超过十五分钟，请重新打开网页“我的”捕获。',
    VERIFY_BUSY:'已有登录校验正在运行。',VERIFY_COOLDOWN:'刚刚已校验过，请一分钟后再试。',
    CAPTURE_CHANGED:'校验期间捕获账号或 Cookie 已变化，请重新手动校验。',
    LOGIN_UNCONFIRMED:'京东未确认登录。请在 Safari 重新登录后捕获；已有已验证 Cookie 保留。',
    MODE_REQUIRED:'请运行“京东网页抓取状态”或“京东网页Cookie校验并保存”。'
  };
  const env = {
    request:typeof $request === 'undefined' ? null : $request,
    mode:typeof $argument === 'string' ? $argument : '',now:() => Date.now(),random:() => Math.random(),
    read:key => $persistentStore.read(key),write:(value,key) => $persistentStore.write(value,key),
    wait:ms => new Promise(resolve => setTimeout(resolve,ms)),done,
    notify:(code,user) => $notification.post('京东网页 Cookie',user || '',messages[code] || '未完成：' + code),
    http:options => new Promise((resolve,reject) => {
      let settled = false;
      const finish = (error,result) => { if (settled) return;settled = true;error ? reject(error) : resolve(result); };
      setTimeout(() => finish(fail('NETWORK_TIMEOUT')),12000);
      try {
        const {method,...request} = options;
        $httpClient[method](request,(error,response,data) => {
          if (error) { finish(fail('NETWORK_ERROR'));return; }
          finish(null,{status:Number(response?.status),body:typeof data === 'string' ? data : ''});
        });
      } catch (_) { finish(fail('NETWORK_ERROR')); }
    })
  };
  runWorkflow(core,env).catch(() => done());
})();

})();
